mapper.update:
UPDATE users
SET display_name = #{displayName}, bio = #{bio}, avatar_url = #{avatarUrl}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, username, display_name, bio, avatar_url, status, role, created_at
FROM users
WHERE username ILIKE #{search} OR display_name ILIKE #{search}
ORDER BY username
LIMIT #{limit}
